from pyspark.sql import functions as F

spark.conf.set("spark.sql.adaptive.enabled", "false")


def profile(df):
    """Run df once, then list the plan steps Spark ran with the counts it kept."""
    df.collect()
    labels = {"numOutputRows": "rows", "shuffleRecordsWritten": "shuffled rows", "numFiles": "files", "filesSize": "bytes"}
    steps = []

    def walk(node, depth):
        name = node.nodeName().strip()
        if name == "AdaptiveSparkPlan":
            return walk(node.executedPlan(), depth)
        if name.endswith("QueryStage"):
            return walk(node.plan(), depth)
        metrics = node.metrics()
        counts = {label: metrics.apply(key).value() for key, label in labels.items() if metrics.contains(key)}
        if counts:
            steps.append(("  " * depth + name, counts))
            depth += 1
        children = node.children()
        for i in range(children.size()):
            walk(children.apply(i), depth)

    walk(df._jdf.queryExecution().executedPlan(), 0)
    return steps


